-- Filipino dishes as recipe estimates.
-- Generated by catalog/build-recipe-foods.mjs from catalog/recipes.json and
-- catalog/usda-ingredients.json. Do not edit by hand: change the recipe and
-- regenerate into a new migration.
--
-- Each dish is the sum of its USDA SR Legacy ingredients (public domain)
-- divided by the finished weight, so every row is 'estimated', never
-- 'verified'. source_ref = 'recipe:<id>' points at the recipe in the repo.

with src (source_ref, name, description, kcal, protein, carbs, fat, fiber, sugar, sodium) as (
  values
    ('recipe:sinigang-na-baboy', 'Sinigang na baboy (pork sinigang)', 'Pork in tamarind broth with radish, string beans, eggplant and greens. Estimated from a home recipe, v1: About 15% of the water evaporates over 90 minutes of simmering. A serving includes broth.', 86.69, 2.84, 2.55, 7.3, null, null, 104.94),
    ('recipe:sinigang-na-hipon', 'Sinigang na hipon (shrimp sinigang)', 'Shrimp in tamarind broth with radish, okra, string beans and greens. Estimated from a home recipe, v1: Shorter cook than pork sinigang, about 10% of the water evaporates.', 26.5, 3.83, 2.82, 0.16, null, null, 123.06),
    ('recipe:pork-adobo', 'Pork adobo', 'Pork shoulder and belly braised in soy sauce, vinegar and garlic. Estimated from a home recipe, v1: Meat loses about a quarter of its weight as water and the sauce reduces by half. Rendered fat stays in the sauce.', 320.19, 14.6, 2.65, 27.35, 0.16, 0.99, 651.05),
    ('recipe:chicken-adobo', 'Chicken adobo', 'Chicken thighs braised in soy sauce, vinegar and garlic. Estimated from a home recipe, v1: Chicken loses about 20% of its weight as water; sauce reduces by half.', 219.66, 15.44, 2.76, 15.82, 0.16, 0.95, 645.26),
    ('recipe:pork-menudo', 'Pork menudo', 'Pork and liver stewed in tomato sauce with potato, carrot, bell pepper, peas and raisins. Estimated from a home recipe, v1: About 15% weight loss from simmering.', 146.32, 9.17, 8.28, 8.58, 1.4, 3.34, 200.74),
    ('recipe:kare-kare', 'Kare-kare', 'Beef and tripe in peanut sauce with eggplant, string beans and pechay. Bagoong not included. Estimated from a home recipe, v1: Most of the water cooks off over 2 to 3 hours. Bagoong is served on the side and must be logged separately.', 143.5, 9, 3.98, 10.47, null, null, 68.9),
    ('recipe:tinola', 'Chicken tinola', 'Chicken in ginger broth with sayote and malunggay. Estimated from a home recipe, v1: About 10% evaporation. A serving includes broth.', 88.84, 7.07, 1.53, 5.97, 0.37, null, 112.08),
    ('recipe:bulalo', 'Bulalo', 'Beef shank and marrow soup with corn, pechay and cabbage. Estimated from a home recipe, v1: About 30% of the water evaporates. Marrow fat varies a lot between bones.', 61.86, 6.85, 1.97, 2.9, 0.35, 0.79, 101.37),
    ('recipe:pancit-canton', 'Pancit canton', 'Stir-fried wheat egg noodles with pork, shrimp and vegetables. Estimated from a home recipe, v1: Noodles absorb most of the liquid; about 10% is lost as steam.', 131.51, 7.04, 15.24, 4.82, 1.43, 1.57, 202.56),
    ('recipe:pancit-bihon', 'Pancit bihon', 'Stir-fried rice noodles with pork, shrimp and vegetables. Estimated from a home recipe, v1: Noodles absorb most of the liquid; about 12% is lost as steam.', 123.79, 5.44, 16.22, 4.01, 1.1, 1.23, 222.91),
    ('recipe:lumpiang-shanghai', 'Lumpiang shanghai', 'Thin fried spring rolls filled with ground pork and vegetables. Estimated from a home recipe, v1: Filling and wrapper lose about 20% of their weight while frying and absorb oil equal to about 10% of raw weight. 25 rolls cut in half.', 338.98, 13.58, 14.91, 24.79, 0.87, null, 272.13),
    ('recipe:lechon-kawali', 'Lechon kawali', 'Pork belly boiled, then deep fried until crisp. Estimated from a home recipe, v1: About 35% of the belly''s fat renders out into the boiling water and frying oil. Weight falls to 65% of raw.', 581.57, 14.37, 0, 57.71, 0, 0, 645.51),
    ('recipe:sisig', 'Pork sisig', 'Chopped grilled pork face, belly and liver with onion, chili and egg. Estimated from a home recipe, v1: Boiling and grilling remove water and some fat before chopping.', 351.23, 17.06, 2.97, 29.74, 0.41, null, 364.84),
    ('recipe:tapsilog', 'Tapsilog', 'Beef tapa, garlic fried rice and a fried egg. One plate. Estimated from a home recipe, v1: Tapa loses about 25% of its weight frying; egg loses about 10%.', 197.05, 9.34, 18.09, 9.38, 0.3, 1.5, 187.86),
    ('recipe:longsilog', 'Longsilog', 'Sweet pork longganisa, garlic fried rice and a fried egg. One plate. Estimated from a home recipe, v1: Sausages lose about 25% of their weight and some fat while frying.', 204.65, 8.1, 19.8, 10.02, 0.29, 3.39, 111.12),
    ('recipe:tocilog', 'Tocilog', 'Sweet cured pork tocino, garlic fried rice and a fried egg. One plate. Estimated from a home recipe, v1: Tocino loses about 25% of its weight while frying.', 213.4, 8.21, 20.44, 10.66, 0.26, 4.26, 114.9),
    ('recipe:sinangag', 'Sinangag (garlic fried rice)', 'Day-old rice fried with garlic. Estimated from a home recipe, v1: Small moisture loss while frying.', 163.3, 2.77, 28.04, 4.13, 0.45, 0.08, 187.79),
    ('recipe:arroz-caldo', 'Arroz caldo', 'Chicken and glutinous rice porridge with ginger. Estimated from a home recipe, v1: About 20% of the water evaporates; the rice absorbs the rest.', 83.52, 4.43, 7.35, 3.87, 0.32, null, 112.39),
    ('recipe:ginisang-monggo', 'Ginisang monggo', 'Mung bean stew with pork, tomato and malunggay. Estimated from a home recipe, v1: About 25% of the water evaporates over an hour; the beans absorb most of the rest.', 105.11, 4.59, 9.89, 5.47, 2.48, 1.32, 139.78),
    ('recipe:champorado', 'Champorado', 'Chocolate glutinous rice porridge with evaporated milk. Estimated from a home recipe, v1: About 25% of the water evaporates while stirring.', 101.16, 1.97, 22.54, 0.96, 1.46, null, 12.21),
    ('recipe:turon', 'Turon', 'Saba banana and jackfruit in a fried caramelized wrapper. Estimated from a home recipe, v1: About 10% moisture loss while frying.', 235.2, 2.01, 43.52, 7.35, 1.51, null, 59.45),
    ('recipe:bibingka', 'Bibingka', 'Baked rice cake with coconut milk, salted egg and cheese. Estimated from a home recipe, v1: About 12% moisture loss in baking. 8 pieces.', 319.4, 6.32, 42, 14.56, 0.69, 17.48, 260.05),
    ('recipe:puto', 'Puto', 'Steamed rice cake. Estimated from a home recipe, v1: Steaming changes the weight very little. 24 small molds.', 231.15, 3.2, 50.9, 1.75, 0.84, 22.51, 239.82),
    ('recipe:pandesal', 'Pandesal', 'Soft bread roll coated in breadcrumbs. Estimated from a home recipe, v1: About 12% moisture loss in baking. 24 rolls.', 330.47, 8.7, 56.95, 7.2, 1.99, 9.04, 456.48)
),
inserted as (
  insert into public.foods (
    name, description, category, calories_per_100g, protein_per_100g,
    carbohydrates_per_100g, fat_per_100g, fiber_per_100g, sugar_per_100g,
    sodium_mg_per_100g, source_name, source_ref, verification_status
  )
  select
    name, description, 'filipino_dish', kcal, protein, carbs, fat,
    fiber::numeric, sugar::numeric, sodium::numeric,
    'Nouri recipe estimate (USDA SR Legacy ingredients)', source_ref, 'estimated'
  from src
  on conflict (source_name, source_ref) do nothing
  returning id, source_ref
),
